mapper.select:
select pia.Pia_Code as piaCode, pia.Pia_Name as piaName, pia.Pia_Area as piaArea, pia.Pia_Type as piaType, c1.C_Name as imaPayeeName, c1.C_Abbreviation as imaPayeeAbbName, pia.Pia_Developer as piaDeveloper,
from Acpm_InvituoMarginApplication mn left join Acpm_ProjectInvestmentApproval pia on pia.id=mn.Acp_id left join Sys_Company c1 on c1.C_Id=mn.Ima_Payee
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
limit #{params.start},#{params.size}
